head.script:
scwin.onpageload = function() {

};

scwin.trigger1_onclick = function() {
	searchbox1.setPlaceholder("바뀐다");
}
scwin.trigger2_onclick = function() {
	searchbox1.setReadOnly("true");
}

scwin.checkVal1 = function() {
    let inputElement = WebSquare.wUnit.getDomById('searchbox1___input');
    let placeholderText = inputElement.getAttribute('placeholder');

    return placeholderText === 'search';
};

scwin.checkVal2 = function() {
    let inputElement = WebSquare.wUnit.getDomById('searchbox1___input');
    let placeholderText = inputElement.getAttribute('placeholder');

    return placeholderText === '바뀐다';
};

scwin.unitTest = function () {
    //Unit 
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal2()", "true");

    //Run test and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
};

scwin.unitTest();
